arguments.query:
WITH cmd_payload AS (
  SELECT time, pid, ppid, pname, process_name, command_line
  FROM audit_logs
  WHERE process_name IN ('cmd.exe', 'payload.exe')
),
context AS (
  SELECT * FROM audit_logs
  WHERE time BETWEEN (
    (SELECT MIN(time) FROM cmd_payload) - INTERVAL 1 MINUTE
  ) AND (
    (SELECT MAX(time) FROM cmd_payload) + INTERVAL 1 MINUTE
  )
)
SELECT time, process_name, pid, ppid, command_line
FROM context
ORDER BY time;

